'use client';
import {useCallback,useEffect,useRef,useState} from 'react';
import {hotelRpc,formText} from '@/lib/pilot';
import {downloadReport,reportUsd} from '@/lib/report-export';
import {paymentMethods,paymentEvidence,paymentText,paymentPendingKey,paymentReviewedSource,paymentSaveArgs,paymentRetireArgs,paymentStatusLabel,paymentSourceLabel,paymentReviewCsv,validatePaymentPending,validatePaymentDetail,validatePaymentResult,validatePaymentStatus,type PaymentScope,type PaymentDetail,type PaymentPending,type PaymentCommand,type PaymentReview,type PaymentMethod,type EvidenceBasis} from '@/lib/payment-record-reviews';

type Props=PaymentScope&{disabled?:boolean;onBusyChange:(busy:boolean)=>void;onBack:()=>void;onSaved?:()=>void};
type Proposal=Pick<PaymentPending,'command'|'reviewed_source'>;
function restored(key:string,scope:PaymentScope){try{const raw=sessionStorage.getItem(key);if(raw===null)return {pending:null,error:''};const value:unknown=JSON.parse(raw);validatePaymentPending(value,scope);return {pending:value,error:''}}catch{return {pending:null,error:'The saved review request could not be read safely. It has been retained. Restore browser storage access or resolve the saved record before another review.'}}}
const capacityErrors=new Set(['Complete payment review history exceeds its3MiB readability budget','Payment review detail exceeds its reserved readable response budget','This payment entry has reached1000 reviews; existing history and request recovery remain available']);
function reviewLabel(r:PaymentReview){return r.method==='unknown'?'Reviewed: method unknown':paymentMethods[r.method]+' · '+paymentEvidence[r.evidence_basis]}
export const paymentReviewStyles='.pilot-payment-review .pilot-actions{flex-wrap:wrap}.pilot-payment-review .pilot-actions .primary{font-size:14px}.pilot-payment-review .payment-source-text{white-space:pre-wrap;overflow-wrap:anywhere}.pilot-payment-review h3{font-size:16px;font-weight:600;margin:20px 0 8px}.pilot-payment-review details{margin:16px 0}.pilot-payment-review .payment-review-history{padding:14px 0;border-bottom:1px solid #dce3ee}';
export function PaymentRecordReviewPanel(props:Props){return <ReviewWorkspace key={[props.actor,props.tenant,props.property,props.reservation,props.entry].join('/')} {...props}/>}
function ReviewWorkspace({actor,tenant,property,reservation,entry,disabled=false,onBusyChange,onBack,onSaved}:Props){
 const scope={actor,tenant,property,reservation,entry},key=paymentPendingKey(scope);
 const [initial]=useState(()=>restored(key,scope));const [storageError,setStorageError]=useState(initial.error);
 const [pending,setPending]=useState<PaymentPending|null>(initial.pending),[data,setData]=useState<PaymentDetail|null>(null),[fresh,setFresh]=useState(false),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState(initial.error),[notice,setNotice]=useState(''),[confirmedOutcome,setConfirmedOutcome]=useState(false),[proposal,setProposal]=useState<Proposal|null>(null),[method,setMethod]=useState<PaymentMethod|''>(''),[basis,setBasis]=useState<EvidenceBasis|''>(''),[retirementReason,setRetirementReason]=useState(''),[formRevision,setFormRevision]=useState(0);
 const controls=useRef({alive:true,sequence:0,locked:false,owned:false}),busyCallback=useRef(onBusyChange),savedCallback=useRef(onSaved);useEffect(()=>{busyCallback.current=onBusyChange;savedCallback.current=onSaved},[onBusyChange,onSaved]);
 const read=useCallback(async()=>{const value=await hotelRpc<unknown>('payment_record_review',{p_tenant:tenant,p_property:property,p_reservation:reservation,p_entry:entry});validatePaymentDetail(value,{actor,tenant,property,reservation,entry});return value},[actor,tenant,property,reservation,entry]);
 useEffect(()=>{const control=controls.current;control.alive=true;const version=++control.sequence;void read().then(value=>{if(control.alive&&version===control.sequence){setData(value);setFresh(true);setLoading(false)}}).catch(()=>{if(control.alive&&version===control.sequence){setFresh(false);setLoading(false);setError(initial.error||'The current payment-record review could not be verified. Refresh before continuing.')}});return()=>{control.alive=false;control.sequence++;if(control.owned){control.owned=false;busyCallback.current(false)}}},[read,initial.error]);
 const blocked=disabled||busy||!!storageError;
 async function task(fn:()=>Promise<unknown>,readOnly=false){const control=controls.current;if(disabled||control.locked||storageError&&!readOnly||!control.alive)return;control.locked=true;control.owned=true;setBusy(true);setError(storageError);busyCallback.current(true);try{await fn()}catch{if(control.alive)setError('The review action could not be completed. Any saved request has been retained.')}finally{control.locked=false;if(control.alive)setBusy(false);if(control.owned){control.owned=false;busyCallback.current(false)}}}
 async function refreshData(){const control=controls.current,version=++control.sequence;setLoading(true);setFresh(false);setProposal(null);try{const value=await read();if(control.alive&&version===control.sequence){setData(value);setFresh(true)}return value}finally{if(control.alive&&version===control.sequence)setLoading(false)}}
 async function refreshReview(){if(storageError){const restoredState=restored(key,scope);setStorageError(restoredState.error);setError(restoredState.error);if(!restoredState.error){setPending(restoredState.pending);setConfirmedOutcome(false)}}await refreshData()}
 function preserve(value:PaymentPending){validatePaymentPending(value,scope);sessionStorage.setItem(key,JSON.stringify(value));if(controls.current.alive)setPending(value)}
 async function confirmed(value:unknown,original:PaymentPending){validatePaymentResult(value,original);if(!controls.current.alive)return;setConfirmedOutcome(true);setNotice(value.outcome==='retired'?'This request was stopped before a review recorded. No financial record changed. Recorded stop reason: '+value.retirement_reason:value.replayed?'The original review was recovered. No duplicate review or financial entry was created.':'Payment record review saved. No financial record or money changed.');setProposal(null);setFresh(false);let cleaned=true;try{sessionStorage.removeItem(key);setPending(null)}catch{cleaned=false;setError('The outcome is confirmed, but the browser could not clear its saved marker. Check the saved request again before a new review.')}try{savedCallback.current?.()}catch{setError('The review outcome is confirmed, but the surrounding view could not refresh.')}if(!controls.current.alive)return;try{await refreshData();if(controls.current.alive&&cleaned){setMethod('');setBasis('');setFormRevision(n=>n+1)}}catch{if(controls.current.alive)setError('The outcome is confirmed, but the latest review could not load. Refresh before another review.')}
 }
 async function send(value:PaymentPending){if(value.retirement_reason!==null||confirmedOutcome&&pending||!fresh||!data?.can_manage)return;await task(async()=>{preserve(value);setConfirmedOutcome(false);setFresh(false);setNotice('');try{await confirmed(await hotelRpc<unknown>('save_payment_record_review',paymentSaveArgs(value)),value)}catch(error){if(controls.current.alive)setError(error instanceof Error&&'code' in error&&error.code==='P0001'&&capacityErrors.has(error.message)?'The service reported a review-history capacity limit. No new review is confirmed. Your exact request remains saved; check its outcome or stop future retries. Existing history and recovery remain available.':'The review outcome is unconfirmed. Its exact request is saved. Check its outcome or stop future retries before preparing another review.')}})}
 async function check(){if(!pending)return;const original=pending;await task(async()=>{setFresh(false);try{const value=await hotelRpc<unknown>('payment_record_review_request_status',{p_tenant:tenant,p_property:property,p_request:original.request_id});validatePaymentStatus(value,original);if(value.found){await confirmed(value.result,original);return}if(controls.current.alive)setNotice('No outcome is confirmed for this request. It remains saved; an earlier request could still complete.');if(!controls.current.alive)return;try{await refreshData()}catch{if(controls.current.alive)setError('The saved request remains unresolved and current review details could not load.')}}catch{if(controls.current.alive)setError('The saved review outcome could not be verified. Keep the exact request and check again.')}})}
 async function retire(form:HTMLFormElement){if(!pending||confirmedOutcome)return;const original=pending;let reason:string;try{reason=original.retirement_reason??paymentText(formText(new FormData(form),'retirementReason'),4,500)}catch{setError('Enter a stop reason with 4–500 characters.');return}await task(async()=>{const value={...original,retirement_reason:reason};preserve(value);setFresh(false);setNotice('');try{await confirmed(await hotelRpc<unknown>('retire_payment_record_review_request',paymentRetireArgs(value)),value)}catch{if(controls.current.alive)setError('Stopping this request is unconfirmed. The original command and stop reason remain saved. Check its outcome or retry stopping it.')}})}
 async function prepare(form:HTMLFormElement){if(pending||!fresh||!data?.can_manage)return;const fields=new FormData(form);let input:Pick<PaymentCommand,'method'|'method_detail'|'evidence_basis'|'evidence_reference'|'reason'>;try{if(!method)throw Error();const evidence=method==='unknown'?'insufficient_evidence':basis;if(!evidence)throw Error();const reference=formText(fields,'evidenceReference').trim();input={method,method_detail:method==='other'?paymentText(formText(fields,'methodDetail'),4,100):null,evidence_basis:evidence,evidence_reference:reference?paymentText(reference,4,200):null,reason:paymentText(formText(fields,'reason'),4,500)}}catch{setError('Choose the method and evidence basis, and review the required details and reason.');return}await task(async()=>{const current=await refreshData();if(!controls.current.alive)return;if(!current.can_manage){setError('Your current role can read reviews but cannot save a new classification.');return}if(current.version>=1000){setError('This record has reached its review-history limit. Its existing history and saved outcomes remain available.');return}const next:Proposal={command:{reservation_id:reservation,entry_id:entry,expected_version:current.version,...input,confirmed:true},reviewed_source:paymentReviewedSource(current.source)};validatePaymentPending({schema_version:1,actor_id:actor,tenant_id:tenant,property_id:property,reservation_id:reservation,entry_id:entry,request_id:crypto.randomUUID(),...next,retirement_reason:null},scope);setProposal(next)})}
 function confirm(){if(!proposal||pending||!fresh||!data?.can_manage)return;void send({schema_version:1,actor_id:actor,tenant_id:tenant,property_id:property,reservation_id:reservation,entry_id:entry,request_id:crypto.randomUUID(),...proposal,retirement_reason:null})}
 const canWrite=fresh&&!!data?.can_manage&&!pending&&!storageError;
 const formatTime=(stamp:string)=>data?new Intl.DateTimeFormat('en-US',{timeZone:data.property.time_zone,dateStyle:'medium',timeStyle:'long'}).format(new Date(stamp)):stamp;
 return <section className="pilot-payment-review"><style>{paymentReviewStyles}</style><p>Review the method and evidence for an existing external payment or refund. This does not record another transaction or change any amount.</p><div className="pilot-actions"><button className="secondary" disabled={disabled||busy} onClick={onBack}>Back</button><button className="secondary" disabled={disabled||busy} onClick={()=>void task(refreshReview,true)}>Refresh review</button><button className="secondary" disabled={blocked||!fresh||!data||!!pending} onClick={()=>{if(data&&fresh)downloadReport('payment-record-review-'+data.generated_at.slice(0,10),paymentReviewCsv(data))}}>Export review history CSV</button></div>
 {error&&<div className="pilot-error" role="alert">{error}</div>}{notice&&<output className="pilot-notice">{notice}</output>}
 {pending&&<section className="pilot-settings"><h3>Resolve saved review request</h3><p><strong>{paymentMethods[pending.command.method]} · {paymentEvidence[pending.command.evidence_basis]}</strong></p><p className="payment-source-text">{pending.reviewed_source.reference} · {reportUsd(pending.reviewed_source.amount_minor)} · {pending.command.reason}</p><p>The original request stays saved until its exact outcome is confirmed.</p><div className="pilot-actions"><button className="secondary" disabled={blocked} onClick={()=>void check()}>Check saved review request</button>{pending.retirement_reason===null&&!confirmedOutcome&&fresh&&data?.can_manage&&<button className="secondary" disabled={blocked} onClick={()=>void send(pending)}>Retry exact review request</button>}</div>{!confirmedOutcome&&<details><summary>Stop future retries</summary><p>If the review already recorded, its original receipt will be recovered. Otherwise this request will be permanently prevented from recording. This does not undo a review or a payment.</p><form onSubmit={e=>{e.preventDefault();void retire(e.currentTarget)}}>{pending.retirement_reason===null?<><label className="field">Reason to stop this request<input name="retirementReason" value={retirementReason} onChange={e=>setRetirementReason(e.target.value)} required minLength={4} maxLength={500} disabled={blocked}/></label><label className="pilot-check"><input type="checkbox" required disabled={blocked}/>I reviewed this request and want to stop future retries if it has not recorded.</label></>:<p className="payment-source-text">Saved stop reason: {pending.retirement_reason}</p>}<button className="secondary" disabled={blocked}>{pending.retirement_reason===null?'Stop retrying this request':'Retry stopping this request'}</button></form></details>}<details><summary>Saved request identity</summary><p>Request {pending.request_id}<br/>Reviewed version {pending.command.expected_version}</p></details></section>}
 {loading&&!data?<output className="pilot-empty">Loading the original record and its reviews…</output>:data&&<><h3>Original financial record</h3><p>{data.reservation.source} · {data.reservation.source_booking_id} · {paymentStatusLabel(data.reservation)}</p>{!fresh&&<p className="pilot-notice">Prior loaded details. Refresh before preparing another review or export.</p>}<div className="detail-grid"><div>Entry<b>{paymentSourceLabel(data.source)}</b></div><div>Original amount<b>{reportUsd(data.source.amount_minor)}</b></div></div><p className="payment-source-text"><strong>Original reference: </strong>{data.source.reference}</p><p className="payment-source-text"><strong>Original reason: </strong>{data.source.reason}</p><p>Recorded {formatTime(data.source.recorded_at)} · {data.property.time_zone}</p><details><summary>Original audit details</summary><p>Recorded by {data.source.actor_id}<br/>Entry {data.source.id}<br/>Original request {data.source.request_id}{data.source.target_entry_id&&<><br/>Original payment target {data.source.target_entry_id}</>}</p></details><h3>Current method review</h3>{data.current_review?<><p><strong>{reviewLabel(data.current_review)}</strong></p>{data.current_review.method_detail&&<p className="payment-source-text">{data.current_review.method_detail}</p>}{data.current_review.evidence_reference&&<p className="payment-source-text">Review evidence reference: {data.current_review.evidence_reference}</p>}<p className="payment-source-text">{data.current_review.reason}</p><p>Reviewed {formatTime(data.current_review.reviewed_at)}.</p></>:<p>Method not reviewed. No payment method has been established by this review system.</p>}<p>Method and evidence statements are operator records; they do not prove processor settlement or counted cash.</p>{data.reviews.length>0&&<details><summary>Review history · {data.reviews.length} recorded reviews</summary>{[...data.reviews].reverse().map(r=><article key={r.id} className="payment-review-history"><h4>Version {r.to_version}{r.id===data.current_review?.id?' · Current':' · Historical'}</h4><p>{reviewLabel(r)}</p>{r.method_detail&&<p className="payment-source-text">{r.method_detail}</p>}{r.evidence_reference&&<p className="payment-source-text">Evidence reference: {r.evidence_reference}</p>}<p className="payment-source-text">{r.reason}</p><p>{formatTime(r.reviewed_at)}</p><details><summary>Review audit details</summary><p>Reviewed by {r.actor_id}<br/>Review {r.id}<br/>Request {r.request_id}</p></details></article>)}</details>}{!data.can_manage&&<p>Your current role can read these records and resolve your own saved requests. Owners and managers add reviews.</p>}<p className="muted">Prepared {formatTime(data.generated_at)}. Booking source/reference/status are current labels; original financial evidence is unchanged.</p></>}
 {canWrite&&!proposal&&data&&<form key={formRevision} onSubmit={e=>{e.preventDefault();void prepare(e.currentTarget)}}><h3>New payment record review</h3><label className="field">Recorded method<select value={method} required disabled={blocked} onChange={e=>{setMethod(e.target.value as PaymentMethod|'');setBasis('')}}><option value="">Choose method</option>{Object.entries(paymentMethods).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label>{method==='other'&&<label className="field">Other method detail<input name="methodDetail" minLength={4} maxLength={100} required disabled={blocked}/></label>}{method==='unknown'?<p>Evidence basis: insufficient evidence. This intentionally records an unresolved method.</p>:<label className="field">Evidence basis<select value={basis} required disabled={blocked} onChange={e=>setBasis(e.target.value as EvidenceBasis|'')}><option value="">Choose evidence basis</option><option value="external_record_reviewed">External record reviewed by operator</option><option value="operator_report_only">Operator statement only</option></select></label>}<label className="field">Review evidence reference{basis==='external_record_reviewed'?' (required)':' (optional)'}<input name="evidenceReference" minLength={4} maxLength={200} required={basis==='external_record_reviewed'} disabled={blocked}/></label><label className="field">Reason for this review<input name="reason" minLength={4} maxLength={500} required disabled={blocked}/></label><p>Use a document label, not card numbers, credentials or bank-account numbers. A repeated label is allowed. Saving the same classification again creates a new intentional review.</p><button className="primary" disabled={blocked||data.version>=1000}>Review classification</button>{data.version>=1000&&<p>The review-history limit is reached. Existing reviews and saved outcomes remain available.</p>}</form>}
 {proposal&&canWrite&&<section className="pilot-settings"><h3>Confirm payment record review</h3><p><strong>{paymentMethods[proposal.command.method]} · {paymentEvidence[proposal.command.evidence_basis]}</strong></p><p className="payment-source-text">Original reference: {proposal.reviewed_source.reference} · {reportUsd(proposal.reviewed_source.amount_minor)}</p>{proposal.command.method_detail&&<p className="payment-source-text">Method detail: {proposal.command.method_detail}</p>}{proposal.command.evidence_reference&&<p className="payment-source-text">Review evidence reference: {proposal.command.evidence_reference}</p>}<p className="payment-source-text">Reason: {proposal.command.reason}</p><form onSubmit={e=>{e.preventDefault();confirm()}}><label className="pilot-check"><input type="checkbox" required disabled={blocked}/>I reviewed this original record and the method/evidence statement. This does not record another payment or refund.</label><div className="pilot-actions"><button className="primary" disabled={blocked}>Confirm record review</button><button type="button" className="secondary" disabled={blocked} onClick={()=>setProposal(null)}>Edit classification</button></div></form></section>}
 </section>;
}
